      final pigeonVar_channel = BasicMessageChannel<Object?>(
          'dev.flutter.pigeon.fruler.DesktopFlutterApi.onEvent$messageChannelSuffix', pigeonChannelCodec,
          binaryMessenger: binaryMessenger);
